Here is the commit message:
chelsio/chtls: fix tls record info to user

chtls_pt_recvmsg() receives a skb with tls header and subsequent
skb with data, need to finalize the data copy whenever next skb
with tls header is available. but here current tls header is
overwritten by next available tls header, ends up corrupting
user buffer data. fixing it by finalizing current record whenever
next skb contains tls header.

v1->v2:
- Improved commit message.

Fixes: 17a7d24aa89d ("crypto: chtls - generic handling of data and hdr")
Signed-off-by: Vinay Kumar Yadav <vinay.yadav@chelsio.com>
Link: https://lore.kernel.org/r/20201022190556.21308-1-vinay.yadav@chelsio.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug occurs because the current TLS header is overwritten by the next available TLS header when processing socket buffers, leading to corruption of the user buffer data. The function `chtls_pt_recvmsg()` fails to finalize the data copy from the current socket buffer before moving on to the next one that contains a TLS header, resulting in incorrect data being sent to the user.

Here is the patch:

 static int chtls_pt_recvmsg(struct sock *sk, struct msghdr *msg, size_t len,
 			    int nonblock, int flags, int *addr_len)
 {
 	struct chtls_sock *csk = rcu_dereference_sk_user_data(sk);
 	struct chtls_hws *hws = &csk->tlshws;
 	struct net_device *dev = csk->egress_dev;
 	struct adapter *adap = netdev2adap(dev);
 	struct tcp_sock *tp = tcp_sk(sk);
 	unsigned long avail;
 	int buffers_freed;
 	int copied = 0;
 	int target;
 	long timeo;

 	buffers_freed = 0;

 	timeo = sock_rcvtimeo(sk, nonblock);
 	target = sock_rcvlowat(sk, flags & MSG_WAITALL, len);

 	if (unlikely(csk_flag(sk, CSK_UPDATE_RCV_WND)))
 		chtls_cleanup_rbuf(sk, copied);

 	do {
 		struct sk_buff *skb;
 		u32 offset = 0;

 		if (unlikely(tp->urg_data &&
 			     tp->urg_seq == tp->copied_seq)) {
 			if (copied)
 				break;
 			if (signal_pending(current)) {
 				copied = timeo ? sock_intr_errno(timeo) :
 					-EAGAIN;
 				break;
 			}
 		}
 		skb = skb_peek(&sk->sk_receive_queue);
 		if (skb)
 			goto found_ok_skb;
 		if (csk->wr_credits &&
 		    skb_queue_len(&csk->txq) &&
 		    chtls_push_frames(csk, csk->wr_credits ==
 				      csk->wr_max_credits))
 			sk->sk_write_space(sk);

 		if (copied >= target && !READ_ONCE(sk->sk_backlog.tail))
 			break;

 		if (copied) {
 			if (sk->sk_err || sk->sk_state == TCP_CLOSE ||
 			    (sk->sk_shutdown & RCV_SHUTDOWN) ||
 			    signal_pending(current))
 				break;

 			if (!timeo)
 				break;
 		} else {
 			if (sock_flag(sk, SOCK_DONE))
 				break;
 			if (sk->sk_err) {
 				copied = sock_error(sk);
 				break;
 			}
 			if (sk->sk_shutdown & RCV_SHUTDOWN)
 				break;
 			if (sk->sk_state == TCP_CLOSE) {
 				copied = -ENOTCONN;
 				break;
 			}
 			if (!timeo) {
 				copied = -EAGAIN;
 				break;
 			}
 			if (signal_pending(current)) {
 				copied = sock_intr_errno(timeo);
 				break;
 			}
 		}
 		if (READ_ONCE(sk->sk_backlog.tail)) {
 			release_sock(sk);
 			lock_sock(sk);
 			chtls_cleanup_rbuf(sk, copied);
 			continue;
 		}

 		if (copied >= target)
 			break;
 		chtls_cleanup_rbuf(sk, copied);
 		sk_wait_data(sk, &timeo, NULL);
 		continue;
 found_ok_skb:
 		if (!skb->len) {
 			skb_dst_set(skb, NULL);
 			__skb_unlink(skb, &sk->sk_receive_queue);
 			kfree_skb(skb);

 			if (!copied && !timeo) {
 				copied = -EAGAIN;
 				break;
 			}

 			if (copied < target) {
 				release_sock(sk);
 				lock_sock(sk);
 				continue;
 			}
 			break;
 		}
 		offset = hws->copied_seq;
 		avail = skb->len - offset;
 		if (len < avail)
 			avail = len;

 		if (unlikely(tp->urg_data)) {
 			u32 urg_offset = tp->urg_seq - tp->copied_seq;

 			if (urg_offset < avail) {
 				if (urg_offset) {
 					avail = urg_offset;
 				} else if (!sock_flag(sk, SOCK_URGINLINE)) {
 					/* First byte is urgent, skip */
 					tp->copied_seq++;
 					offset++;
 					avail--;
 					if (!avail)
 						goto skip_copy;
 				}
 			}
 		}
 		/* Set record type if not already done. For a non-data record,
 		 * do not proceed if record type could not be copied.
 		 */
 		if (ULP_SKB_CB(skb)->flags & ULPCB_FLAG_TLS_HDR) {
 			struct tls_hdr *thdr = (struct tls_hdr *)skb->data;
 			int cerr = 0;

 			cerr = put_cmsg(msg, SOL_TLS, TLS_GET_RECORD_TYPE,
 					sizeof(thdr->type), &thdr->type);

 			if (cerr && thdr->type != TLS_RECORD_TYPE_DATA)
 				return -EIO;
 			/*  don't send tls header, skip copy */
 			goto skip_copy;
 		}

 		if (skb_copy_datagram_msg(skb, offset, msg, avail)) {
 			if (!copied) {
 				copied = -EFAULT;
 				break;
 			}
 		}

 		copied += avail;
 		len -= avail;
 		hws->copied_seq += avail;
 skip_copy:
 		if (tp->urg_data && after(tp->copied_seq, tp->urg_seq))
 			tp->urg_data = 0;

 		if ((avail + offset) >= skb->len) {
+			struct sk_buff *next_skb;
 			if (ULP_SKB_CB(skb)->flags & ULPCB_FLAG_TLS_HDR) {
 				tp->copied_seq += skb->len;
 				hws->rcvpld = skb->hdr_len;
 			} else {
 				atomic_inc(&adap->chcr_stats.tls_pdu_rx);
 				tp->copied_seq += hws->rcvpld;
 			}
 			chtls_free_skb(sk, skb);
 			buffers_freed++;
 			hws->copied_seq = 0;
-			if (copied >= target &&
-			    !skb_peek(&sk->sk_receive_queue))
+			next_skb = skb_peek(&sk->sk_receive_queue);
+			if (copied >= target && !next_skb)
+				break;
+			if (ULP_SKB_CB(next_skb)->flags & ULPCB_FLAG_TLS_HDR)
 				break;
 		}
 	} while (len > 0);

 	if (buffers_freed)
 		chtls_cleanup_rbuf(sk, copied);
 	release_sock(sk);
 	return copied;
 }



